        // cofactor lies in [-2^(2N),2^(2N)]; top is -1, 0 or 1.
        ulong sign = (ulong)(top >> 63), c = 0;
        const ulong X0 = 0xcff7fffffffd5558UL;
        const ulong X1 = 0xf55ffff58a9ffffdUL;
        const ulong X2 = 0x39869507b587b120UL;
        const ulong X3 = 0x23ba5c279c2895fbUL;
        const ulong X4 = 0x58dd3db21a5d66bbUL;
        const ulong X5 = 0xd0088f51cbff34d2UL;
        ulong h0 = AddCarry(value.L6, X0 & sign, ref c);
        ulong h1 = AddCarry(value.L7, X1 & sign, ref c);
        ulong h2 = AddCarry(value.L8, X2 & sign, ref c);
        ulong h3 = AddCarry(value.L9, X3 & sign, ref c);
        ulong h4 = AddCarry(value.L10, X4 & sign, ref c);
        ulong h5 = AddCarry(value.L11, X5 & sign, ref c);
        top += (long)c;
        ulong adjust = ~InverseBatch.ZeroMask((ulong)top);
        sign = (ulong)(-top >> 63);
        c = sign & 1;
        ulong x0 = AddCarry((X0 & adjust) ^ sign, 0, ref c);
        ulong x1 = AddCarry((X1 & adjust) ^ sign, 0, ref c);
        ulong x2 = AddCarry((X2 & adjust) ^ sign, 0, ref c);
        ulong x3 = AddCarry((X3 & adjust) ^ sign, 0, ref c);
        ulong x4 = AddCarry((X4 & adjust) ^ sign, 0, ref c);
        ulong x5 = AddCarry((X5 & adjust) ^ sign, 0, ref c);
        c = 0;
        h0 = AddCarry(h0, x0, ref c);
        h1 = AddCarry(h1, x1, ref c);
        h2 = AddCarry(h2, x2, ref c);
        h3 = AddCarry(h3, x3, ref c);
        h4 = AddCarry(h4, x4, ref c);
        h5 = AddCarry(h5, x5, ref c);
        // Corrected value is in [0,R^2). Canonicalize its high half
        // before REDC, so the sum with REDC(low) is below 2*modulus.
        ulong borrow3 = 0;
        ulong s3_0 = SubBorrow(h0, 0xcff7fffffffd5558UL, ref borrow3);
        ulong s3_1 = SubBorrow(h1, 0xf55ffff58a9ffffdUL, ref borrow3);
        ulong s3_2 = SubBorrow(h2, 0x39869507b587b120UL, ref borrow3);
        ulong s3_3 = SubBorrow(h3, 0x23ba5c279c2895fbUL, ref borrow3);
        ulong s3_4 = SubBorrow(h4, 0x58dd3db21a5d66bbUL, ref borrow3);
        ulong s3_5 = SubBorrow(h5, 0xd0088f51cbff34d2UL, ref borrow3);
        ulong mask3 = borrow3 - 1;
        h0 = InverseBatch.Select(s3_0, h0, mask3);
        h1 = InverseBatch.Select(s3_1, h1, mask3);
        h2 = InverseBatch.Select(s3_2, h2, mask3);
        h3 = InverseBatch.Select(s3_3, h3, mask3);
        h4 = InverseBatch.Select(s3_4, h4, mask3);
        h5 = InverseBatch.Select(s3_5, h5, mask3);
        ulong borrow2 = 0;
        ulong s2_0 = SubBorrow(h0, 0xe7fbfffffffeaaacUL, ref borrow2);
        ulong s2_1 = SubBorrow(h1, 0x7aaffffac54ffffeUL, ref borrow2);
        ulong s2_2 = SubBorrow(h2, 0x9cc34a83dac3d890UL, ref borrow2);
        ulong s2_3 = SubBorrow(h3, 0x91dd2e13ce144afdUL, ref borrow2);
        ulong s2_4 = SubBorrow(h4, 0x2c6e9ed90d2eb35dUL, ref borrow2);
        ulong s2_5 = SubBorrow(h5, 0x680447a8e5ff9a69UL, ref borrow2);
        ulong mask2 = borrow2 - 1;
        h0 = InverseBatch.Select(s2_0, h0, mask2);
        h1 = InverseBatch.Select(s2_1, h1, mask2);
        h2 = InverseBatch.Select(s2_2, h2, mask2);
        h3 = InverseBatch.Select(s2_3, h3, mask2);
        h4 = InverseBatch.Select(s2_4, h4, mask2);
        h5 = InverseBatch.Select(s2_5, h5, mask2);
        ulong borrow1 = 0;
        ulong s1_0 = SubBorrow(h0, 0x73fdffffffff5556UL, ref borrow1);
        ulong s1_1 = SubBorrow(h1, 0x3d57fffd62a7ffffUL, ref borrow1);
        ulong s1_2 = SubBorrow(h2, 0xce61a541ed61ec48UL, ref borrow1);
        ulong s1_3 = SubBorrow(h3, 0xc8ee9709e70a257eUL, ref borrow1);
        ulong s1_4 = SubBorrow(h4, 0x96374f6c869759aeUL, ref borrow1);
        ulong s1_5 = SubBorrow(h5, 0x340223d472ffcd34UL, ref borrow1);
        ulong mask1 = borrow1 - 1;
        h0 = InverseBatch.Select(s1_0, h0, mask1);
        h1 = InverseBatch.Select(s1_1, h1, mask1);
        h2 = InverseBatch.Select(s1_2, h2, mask1);
        h3 = InverseBatch.Select(s1_3, h3, mask1);
        h4 = InverseBatch.Select(s1_4, h4, mask1);
        h5 = InverseBatch.Select(s1_5, h5, mask1);
        ulong borrow0 = 0;
        ulong s0_0 = SubBorrow(h0, 0xb9feffffffffaaabUL, ref borrow0);
        ulong s0_1 = SubBorrow(h1, 0x1eabfffeb153ffffUL, ref borrow0);
        ulong s0_2 = SubBorrow(h2, 0x6730d2a0f6b0f624UL, ref borrow0);
        ulong s0_3 = SubBorrow(h3, 0x64774b84f38512bfUL, ref borrow0);
        ulong s0_4 = SubBorrow(h4, 0x4b1ba7b6434bacd7UL, ref borrow0);
        ulong s0_5 = SubBorrow(h5, 0x1a0111ea397fe69aUL, ref borrow0);
        ulong mask0 = borrow0 - 1;
        h0 = InverseBatch.Select(s0_0, h0, mask0);
        h1 = InverseBatch.Select(s0_1, h1, mask0);
        h2 = InverseBatch.Select(s0_2, h2, mask0);
        h3 = InverseBatch.Select(s0_3, h3, mask0);
        h4 = InverseBatch.Select(s0_4, h4, mask0);
        h5 = InverseBatch.Select(s0_5, h5, mask0);
        ulong t0 = value.L0;
        ulong t1 = value.L1;
        ulong t2 = value.L2;
        ulong t3 = value.L3;
        ulong t4 = value.L4;
        ulong t5 = value.L5;
        for (int row = 0; row < 6; row++)
        {
            ulong q = t0 * N0;
            ulong carry = MulAdd(q, M0, t0, 0, out _);
            carry = MulAdd(q, M1, t1, carry, out t0);
            carry = MulAdd(q, M2, t2, carry, out t1);
            carry = MulAdd(q, M3, t3, carry, out t2);
            carry = MulAdd(q, M4, t4, carry, out t3);
            carry = MulAdd(q, M5, t5, carry, out t4);
            t5 = carry;
        }
        c = 0;
        h0 = AddCarry(h0, t0, ref c);
        h1 = AddCarry(h1, t1, ref c);
        h2 = AddCarry(h2, t2, ref c);
        h3 = AddCarry(h3, t3, ref c);
        h4 = AddCarry(h4, t4, ref c);
        h5 = AddCarry(h5, t5, ref c);
        Reduce(out Fp reduced, h0, h1, h2, h3, h4, h5);
        // T=2N steps give v*input=R^2 modulo the modulus. REDC then
        // multiplication by R^2 restores the inverse Montgomery representation.
        Multiply(out result, reduced, R2);
    }

    internal struct InverseNarrow
    {
        internal ulong L0;
        internal ulong L1;
        internal ulong L2;
        internal ulong L3;
        internal ulong L4;
        internal ulong L5;
        internal ulong L6;
    }
    internal struct InverseWide
    {
        internal ulong L0;
        internal ulong L1;
        internal ulong L2;
        internal ulong L3;
        internal ulong L4;
        internal ulong L5;
        internal ulong L6;
        internal ulong L7;
        internal ulong L8;
        internal ulong L9;
        internal ulong L10;
        internal ulong L11;
    }
}
